#include "../opponents/v87-tail-return/tail_escape.hpp"
#include <cassert>
#include <iostream>
using namespace unswbc;
int main(){Game board{15,15,64};Controller bot{0,Team::A,Direction::NORTH,Vision{},64};game=&board;ct=&bot;std::vector<Tile> tiles;for(int y=2;y<=8;++y)for(int x=2;x<=8;++x){tiles.emplace_back(Position{x,y},std::nullopt,-1);for(auto d:Direction::get_direction_list())tiles.back().get_edge(d).edge_type=EdgeType::KELP;}bot.vision=Vision{std::move(tiles)};auto open=[&](Position p,Direction d){bot.get_tile(p)->get_edge(d).edge_type=EdgeType::EMPTY;bot.get_tile(p.add_dir(d))->get_edge(d.get_opposite()).edge_type=EdgeType::EMPTY;};open({5,5},Direction::EAST);open({6,5},Direction::SOUTH);open({6,6},Direction::WEST);open({5,6},Direction::NORTH);bot.head.position={5,5};bot.length=4;strategy::Memory m;m.body={{5,5},{5,6},{6,6},{6,5}};m.observe_map(bot,100);strategy::Simulation s{m.body,{},true,4};auto route=strategy::tail_route(bot,m,s);assert(!route.connected && !route.uncertain && route.space==1);open({5,5},Direction::NORTH);open({5,4},Direction::EAST);open({6,4},Direction::SOUTH);m.observe_map(bot,101);assert(strategy::tail_route(bot,m,s).connected);std::cout<<"Adjacent occupied tail is not immediately safe; an actual detour connects it.\n";}
